  else if(!grind){skater.position.y=0;skater.rotation.z=THREE.MathUtils.lerp(skater.rotation.z,-steer*.14,.12);board.rotation.z=THREE.MathUtils.lerp(board.rotation.z,-steer*.04,.12)}
  const f=keys.f;if(f&&!lastFlux)tryFlux();lastFlux=f;
